'use strict';
// Generado por tools/build-mechanics.mjs a partir de tools/mechanics_es.json
const MECH_DATA = {"raid":"El Abismo Venenoso (Midnight S2 / 12.1) + Gruta Ligada a la Marea + El Desatamiento de Kith'ix (12.1.5)","types":{"tanque":{"color":"#8a5a2b","label":"Tanque"},"cortable":{"color":"#2f6bff","label":"Cortable / Interrumpir"},"oneshot":{"color":"#dc2626","label":"One-shot / Letal"},"dispel":{"color":"#9333ea","label":"Dispel"},"raidwide":{"color":"#f97316","label":"Daño de raid"},"soak":{"color":"#16a34a","label":"Soak / Grupo"},"add":{"color":"#eab308","label":"Add / Prioridad"},"avoid":{"color":"#06b6d4","label":"Evitar / Suelo"},"enrage":{"color":"#111827","label":"Enrage / Wipe"}},"bosses":[{"slug":"nekzali","name":"Nek'zali la Volutadora de Almas","wing":"Ala 1: Los Volutadores de Almas","order":1,"phases":[{"phase":"Fase 1","mechanics":[{"name":"Tromba de posesión","type":"tanque","diffs":["N","H","M"],"note":"Nek'zali lanza 4 ecos espectrales hacia su objetivo principal (hechizo de 6 s): cada uno explota al primer jugador que toca y hace daño de las Sombras a toda la banda, que baja cuanto más ha recorrido el eco. El tanque se queda a más de 30 m del jefe y nadie se pone en la línea entre los dos.","verified":true},{"name":"Golpes desgarradores","type":"tanque","diffs":["N","H","M"],"note":"Los ataques cuerpo a cuerpo le arrebatan parte del alma al objetivo: daño de las Sombras cada 3 s y −5 % por acumulación de las sanaciones y absorciones que recibe. Hay que cambiar de tanque con un 30-40 % de reducción.","verified":true},{"name":"Desgarro de esencia","type":"dispel","diffs":["N","H","M"],"note":"Canalización de 5 s: atrapa la esencia de varios jugadores y los atrae 5 s antes de dañarlos y repelerlos. La esencia fantasmal sigue dañando 15 s; al terminar o al disiparse aparece un Cultor latente en ese punto. Hay que llevarla a un lado de la sala y disiparla allí o apilarse y disipar en masa.","verified":true},{"name":"Cultor latente","type":"avoid","diffs":["N","H","M"],"note":"El espíritu de un cultor se materializa y explota: daño de las Sombras a los jugadores a 6 m y deja una zona de energía necrótica que hace daño cada 1 s y reduce la velocidad de movimiento un 40 %. Hay que colocarla donde luego no haga falta pasar.","verified":true},{"name":"Amani inquieto","type":"add","diffs":["N","H","M"],"note":"Los espíritus antiguos regresan a sus cadáveres, salen de los sarcófagos laterales y caminan hacia el Pozo de volutas de almas. Cada uno que llega al pozo activa un Rito de voluta de almas. Hay que matarlos antes de que lleguen, sin dejar que varios lleguen seguidos.","verified":true},{"name":"Avance sepulcral","type":"add","diffs":["N","H","M"],"note":"Los Amani inquietos llevan una barrera necrótica que absorbe daño mágico igual al 25 % de su vida y mientras dure no pueden morir. Hay que romperla con daño mágico y matarlos antes de que lleguen al pozo.","verified":true},{"name":"Añublo cadavérico","type":"raidwide","diffs":["N","H","M"],"note":"Cuando muere un Amani inquieto estalla en necrosis: daño de Peste a todos y un DoT de 15 s acumulable. En Heroico y Mítico deja además un Receptáculo del despertar.","verified":true},{"name":"Rito de voluta de almas","type":"raidwide","diffs":["N","H","M"],"note":"Cada vez que se alimenta el pozo, Nek'zali gana 5 de energía y todos reciben daño de las Sombras y un DoT de 44 s acumulable. Al llegar a 100 de energía lanza la Ira involutada.","verified":true},{"name":"Quemadura ritual","type":"raidwide","diffs":["H","M"],"note":"Aumenta un 15 % el daño recibido de los siguientes Ritos de voluta de almas durante 1 min, acumulable. Conviene llegar a la Ignición con cero acumulaciones.","verified":true},{"name":"Ignición de voluta de almas","type":"raidwide","diffs":["N","H","M"],"note":"Nek'zali agita el pozo y lanza un Rito de voluta de almas por segundo durante 4 s. Durante la canalización caen Ecos angustiados del pozo. Es una comprobación de sanación: cooldowns de banda y cero acumulaciones de Quemadura ritual.","verified":true},{"name":"Ecos angustiados","type":"avoid","diffs":["N","H","M"],"note":"Durante la Ignición aparecen espíritus angustiados en el suelo: daño de las Sombras a quien esté a 5 m del impacto y repulsión. Hay que esquivar los círculos.","verified":true},{"name":"Profundidades aferradoras","type":"avoid","diffs":["M"],"note":"Mítico. Un eco ahogado despierta dentro del pozo y atrae a los jugadores hacia él: todos reciben daño de las Sombras cada 1 s hasta que muere. Ocurre dos veces en la Fase 1, dos en el intermedio y dos en la Fase 2: se asignan dos equipos de 3 DPS y 1 sanador, uno por cada aparición. Si el eco agarra a alguien lo mata y se activa un Rito de voluta de almas.","verified":true},{"name":"Maldición de los Volutadores de Almas","type":"cortable","diffs":["M"],"note":"Mítico. El eco ahogado lanza (10 s) una maldición que aferra a todos los jugadores del pozo, los expulsa y les aplica Almavolutada. Es la interrupción que importa.","verified":true},{"name":"Agotamiento de alma","type":"avoid","diffs":["M"],"note":"Mítico. Quien sale del pozo queda marcado: recibe un 300 % más de daño del Pozo de volutas de almas y de la Espiral inmortal. El mismo equipo debe quedarse dentro y no entrar y salir.","verified":true},{"name":"Espiral inmortal","type":"raidwide","diffs":["M"],"note":"Mítico. La energía necrótica del pozo hace daño de las Sombras cada 1 s a los jugadores asignados mientras el eco ahogado siga vivo.","verified":true},{"name":"Espíritu arremolinado","type":"avoid","diffs":["M"],"note":"Mítico. Los espíritus del interior del pozo hacen daño de las Sombras cada 1 s durante 5 s al entrar en contacto, acumulable.","verified":true}]},{"phase":"Intermedio (Ritual del despertar)","mechanics":[{"name":"Ritual del despertar","type":"add","diffs":["N","H","M"],"note":"Al llegar al 50 % de salud, la invocadora Jawae activa las Ataduras del despertar: Nek'zali se retira al pozo, inmune a todo el daño, y no se puede dañar hasta matar a los dos Ecos de Jawae que la atan al pozo.","verified":true},{"name":"Transferencia de alma","type":"avoid","diffs":["N","H","M"],"note":"Jawae transfiere su esencia a un eco durante 15 s y después una oleada de energía de alma hace daño enorme de las Sombras a quien esté dentro de la explosión. Hay que salir del haz antes de que acabe.","verified":true},{"name":"Pira hambrienta","type":"soak","diffs":["N","H","M"],"note":"El Eco de Jawae estalla en fuego de alma (7,5 s): daño de Fuego dividido entre todos los jugadores a 10 m, que además quema los cadáveres. Lo absorbe el grupo cuerpo a cuerpo; los que no absorben reciben Llama serpenteante.","verified":true},{"name":"Llama serpenteante","type":"avoid","diffs":["N","H","M"],"note":"Una llama persigue a quien no absorbió la pira y estalla: daño de Fuego y un DoT de 8 s. Los que no absorben pueden pasarla sobre los cadáveres para quemarlos. En Heroico y Mítico, al expirar explota como Cremación.","verified":true},{"name":"Cremación","type":"avoid","diffs":["H","M"],"note":"La llama explota en 4 m: incinera cadáveres y Amani inquietos y daña a los jugadores con Fuego y un DoT de 20 s.","verified":true},{"name":"Receptáculo del despertar","type":"add","diffs":["H","M"],"note":"Cada Amani muerto en la Fase 1 deja un cadáver. Durante el ritual otro Amani inquieto lo posee y revive potenciado, con una aura que pulsa daño. En Mítico es obligatorio limpiar los cadáveres (con Piras, Llamas o Cremación) y permitir solo una resurrección a la vez.","verified":true}]},{"phase":"Fase 2","mechanics":[{"name":"Involutándose","type":"raidwide","diffs":["N","H","M"],"note":"Nek'zali vuelca su poder en el pozo, que se desborda: daño de las Sombras a toda la banda cada 0,9 s hasta su muerte. Es un enrage blando: hay que sanarlo y matarla rápido.","verified":true},{"name":"Invocar","type":"avoid","diffs":["N","H","M"],"note":"Hechizo de 5 s: Nek'zali activa un Rito de voluta de almas y ordena a todos los Cultores latentes dar un Paso entrelazado, reposicionándose alrededor del pozo. Hay que esquivar las zonas que se mueven. En Mítico interrumpe todos los lanzamientos y silencia 3 s a quien interrumpa: hay que parar los propios hechizos antes.","verified":true},{"name":"Ira involutada","type":"enrage","diffs":["N","H","M"],"note":"Al llegar a 100 de energía: +500 % de daño, +150 % de velocidad de ataque y movimiento e inmunidad a provocaciones. Es un wipe seguro: hay que matar a Nek'zali antes.","verified":true}]}]},{"slug":"entombed-sentinels","name":"Centinelas Sepultados","wing":"Ala 2: La Esencia del Veneno","order":2,"phases":[{"phase":"General","mechanics":[{"name":"Dominio de Ula'tek","type":"avoid","diffs":["N","H","M"],"note":"Si los 2 centinelas se juntan a <40m, reciben un 99% menos de daño — no los juntes.","verified":true},{"name":"Estasis vitriólica","type":"raidwide","diffs":["N","H","M"],"note":"Si el DPS no está balanceado entre los dos jefes, se curan entre sí.","verified":true},{"name":"Marca de ácido / Marca de sangre","type":"tanque","diffs":["N","H","M"],"note":"Marca con daño acumulado cerca de cada jefe; cambio de tanque tras cada intermedio.","verified":true}]},{"phase":"Aliento de Ula'tek","mechanics":[{"name":"Gotitas tóxicas","type":"avoid","diffs":["N","H","M"],"note":"Adds pequeños que hay que pisar antes de que exploten.","verified":true},{"name":"Veneno viviente","type":"avoid","diffs":["H","M"],"note":"Tras destruir las gotitas, el veneno vuelve hacia el jefe — evitar su camino.","verified":true},{"name":"Coagulación de veneno","type":"add","diffs":["N","H","M"],"note":"Add grande que lanza Contaminar mientras viva — prioridad de muerte.","verified":true},{"name":"Embate potenciador","type":"tanque","diffs":["N","H","M"],"note":"Golpe físico que crece cada vez que impacta al mismo tanque.","verified":true}]},{"phase":"Sangre de Ula'tek","mechanics":[{"name":"Miasma inestable","type":"soak","diffs":["N","H","M"],"note":"Marca a un jugador; tras 8s explota repartiendo el daño entre quien la soakea.","verified":true},{"name":"Oscuridad pegajosa","type":"raidwide","diffs":["N","H","M"],"note":"Veneno de Sombras acumulado en soakers; en Heroico deja un charco al expirar.","verified":true},{"name":"Veneno de sangre","type":"avoid","diffs":["H","M"],"note":"Charco tóxico en el suelo — agrupar cerca del borde para no gastar espacio.","verified":true},{"name":"Sangre contagiada","type":"dispel","diffs":["N","H","M"],"note":"Veneno disipable que infecta a los jugadores — dispelar rápido.","verified":true},{"name":"Inyección de veneno de sangre","type":"tanque","diffs":["N","H","M"],"note":"Golpe físico grande que aumenta de intensidad con cada golpe al mismo objetivo.","verified":true}]},{"phase":"Intermedio","mechanics":[{"name":"Estasis vitriólica (Intermedio)","type":"raidwide","diffs":["N","H","M"],"note":"Ambos jefes igualan vida al mayor; el de menos vida se cura.","verified":true},{"name":"Toxinas helicoidales","type":"oneshot","diffs":["N","H","M"],"note":"Veneno de sangre — colisionar para sumar exactamente 4; en Heroico pasarse de 4 mata.","verified":true}]},{"phase":"Mítico","mechanics":[{"name":"Protoveneno cambiante","type":"avoid","diffs":["M"],"note":"Contamina a jugadores aleatorios con Peste; dos contaminados que se tocan se neutralizan, contaminado+sano = Erupción de protoveneno.","verified":true},{"name":"Erupción de protoveneno","type":"avoid","diffs":["M"],"note":"Explosión que daña y repele a los cercanos cuando un contaminado toca a uno no contaminado.","verified":true}]}]},{"slug":"vashnik","name":"Vashnik el Maligno","wing":"Ala 2: La Esencia del Veneno","order":3,"phases":[{"phase":"Todo el combate","mechanics":[{"name":"Imbuir","type":"raidwide","diffs":["N","H","M"],"note":"Al llegar a 100 de energía (hechizo de 4 s) Vashnik bebe de las dos fuentes más cercanas: daño a toda la banda y una acumulación de Vapor tóxico. Cada fuente estalla (Expulsión de conflagración, de penumbra o Hemoexpulsión) y suelta venenos vivientes que se arrastran hacia la cavidad maligna. La posición de Vashnik decide qué fuentes se drenan, así que los tanques lo colocan antes de cada Imbuir. Hay que usar cooldowns de sanación.","verified":true},{"name":"Vapor tóxico","type":"raidwide","diffs":["N","H","M"],"note":"Cada Imbuir añade una acumulación permanente: daño de Naturaleza a toda la banda cada 2 s, acumulable. Es el enrage blando: hay que sanarlo y matar a Vashnik rápido para limitar las acumulaciones.","verified":true},{"name":"Ráfaga maligna","type":"oneshot","diffs":["N","H","M"],"note":"Si un veneno viviente llega a la cavidad maligna del centro, explota (1,5 s): daño enorme de Naturaleza a toda la banda y un DoT de 30 s acumulable. Hay que matar a todos los adds antes de que lleguen al centro.","verified":true},{"name":"Infusión de llamas","type":"raidwide","diffs":["N","H","M"],"note":"Cada fuente de llamas drenada da a Vashnik una infusión de 1,5 min, acumulable: potencia su siguiente Imbuir (+100 % de daño de Expulsión de conflagración) y aumenta un 50 % la vida máxima de los venenos ardientes.","verified":true},{"name":"Infusión de Sombras","type":"raidwide","diffs":["N","H","M"],"note":"Cada fuente de las Sombras drenada da a Vashnik una infusión de 1,5 min, acumulable: potencia su siguiente Imbuir (+100 % de daño de Expulsión de penumbra) y aumenta un 50 % la vida máxima de los venenos velados. Las infusiones activas anticipan la infección que vendrá.","verified":true},{"name":"Entereza sanguínea","type":"add","diffs":["N","H","M"],"note":"Fuente de sangre: el veneno coagulador es inmune al control de masas hasta que muere y se divide en trozos más pequeños al morir. Hay que matarlo enseguida y eliminar todos los trozos. Genera Infección succionadora. Solo aparece si se drena la fuente de sangre.","verified":true},{"name":"Revestimiento de miasma","type":"add","diffs":["H","M"],"note":"Fuente de las Sombras: el veneno velado absorbe un 100 % de su vida máxima, por lo que hay que matarlo dos veces. Se puede controlar con CC mientras se limpian los prioritarios. Genera Infección estigia.","verified":true},{"name":"Eyección umbría","type":"avoid","diffs":["N","H","M"],"note":"Los venenos velados explotan al destruirlos: veneno de las Sombras a quien esté a 3 m de los puntos de impacto. Hay que elegir dónde caen los círculos y esquivarlos.","verified":true},{"name":"Presencia ardiente","type":"raidwide","diffs":["N","H","M"],"note":"Fuente de llamas: el veneno ardiente irradia fuego a toda la banda cada 3 s mientras viva (hay 2 por drenaje en Heroico y 3 en Mítico). Es la prioridad de muerte número uno: se controla uno y se mata el otro, nunca a la vez. Genera Infección explosiva.","verified":true},{"name":"Oleada cáustica","type":"raidwide","diffs":["N","H","M"],"note":"Los venenos ardientes explotan al destruirse: daño de Fuego a toda la banda y, en Heroico y Mítico, un DoT acumulable. Hay que matarlos escalonados.","verified":true},{"name":"Veneno endurecido","type":"add","diffs":["N","H","M"],"note":"Cualquier add que siga vivo tras 60 s se vuelve inmune al control de masas y un 50 % más rápido. Hay que matarlos al aparecer.","verified":true},{"name":"Catalizador maligno","type":"raidwide","diffs":["H","M"],"note":"Vashnik coagula un orbe de veneno sobre la cavidad maligna (5 s) y lo detona: daño de Naturaleza a todos y lanza Bilis catalítica por la sala.","verified":true},{"name":"Bilis catalítica","type":"soak","diffs":["H","M"],"note":"Una pulverización tóxica daña a los jugadores a 6 m de cada impacto. Si no golpea al menos a un jugador, toda la banda recibe un golpe grande: hay que poner al menos a uno en cada impacto sin amontonar a todos en el mismo.","verified":true},{"name":"Espuma pestilente","type":"avoid","diffs":["N","H","M"],"note":"Vashnik cubre a varios jugadores con veneno corrosivo (2 s): daño de Peste a quien esté a 4,5 m durante 6 s. Los marcados se apartan de la banda y no se colocan donde esté Vashnik.","verified":true},{"name":"Ola de peste","type":"avoid","diffs":["N","H","M"],"note":"Cuando termina la Espuma pestilente salen varias oleadas en las cuatro direcciones cardinales desde el jugador: daño enorme de Peste a quien golpeen. El resto de la banda se mantiene fuera de los ejes.","verified":true},{"name":"Infección succionadora","type":"avoid","diffs":["N","H","M"],"note":"Fuente de sangre. Veneno de sangre sobre varios jugadores: daño de las Sombras, absorbe sanación y reduce a cero la que recibe el infectado, que lanza Succionar sangre a los cercanos para curarse. Los infectados se agrupan para que tenga aliados de los que absorber (se acuerda de antemano). Solo se ve al drenar la fuente de sangre.","verified":true},{"name":"Infección estigia","type":"avoid","diffs":["N","H","M"],"note":"Fuente de las Sombras. Veneno sobre varios jugadores: daño de las Sombras y absorbente de sanación. Los infectados lanzan periódicamente Ráfaga estigia (daño a 3,5 m del impacto), así que se separan del grupo.","verified":true},{"name":"Infección explosiva","type":"dispel","diffs":["N","H","M"],"note":"Fuente de llamas. Veneno de fuego sobre varios jugadores: daño cada 1,5 s. Al disiparse o expirar, el jugador explota (Explosión cáustica) con daño de Fuego a todos los demás: hay que disipar de uno en uno cuando la banda esté estable.","verified":true},{"name":"Colmillos goteantes","type":"tanque","diffs":["N","H","M"],"note":"Vashnik muerde al objetivo actual (2 s): daño físico enorme, un DoT de Naturaleza de 32 s y mucho más daño físico recibido, acumulable. Hay que cambiar de tanque en cada lanzamiento.","verified":true},{"name":"Tótem maligno","type":"add","diffs":["M"],"note":"Mítico. Poco después de la pull y con cada Imbuir las fuentes arrojan tumores malignos al azar en tu mitad de la sala; no se pueden atacar y empiezan a lanzar Malicia al crearse. Se eliminan golpeándolos con las olas de la Espuma pestilente (brillan en blanco cuando una ola apunta a ellos): primera tanda en marcas, segunda improvisando por comunicación.","verified":true},{"name":"Malicia","type":"oneshot","diffs":["M"],"note":"Mítico. Si queda algún tótem al lanzarse Imbuir, libera una oleada de veneno: daño enorme de Naturaleza y un DoT de 1 min acumulable a toda la banda. Con uno se sobrevive; con dos acumulados es wipe, así que hay que limpiar los tótems antes del Imbuir.","verified":true}]}]},{"slug":"lost-explorers","name":"Los exploradores perdidos","wing":"Ala 3: La Madriguera de la Sierpe","order":4,"phases":[{"phase":"General","mechanics":[{"name":"Frente unido","type":"avoid","diffs":["N","H","M"],"note":"Si los 3 jefes están a <30m entre sí, reciben un 99% menos de daño — no los juntes.","verified":true},{"name":"Ascensión final","type":"oneshot","diffs":["N","H","M"],"note":"Canalización letal de Mor'zahi si nadie alimenta a un jefe antes de que acabe.","verified":true}]},{"phase":"Trader Gebbo","mechanics":[{"name":"Lanzar trastos","type":"avoid","diffs":["N","H","M"],"note":"Cajones lanzados por la sala; romperlos aplica Astillas (sangrado acumulado).","verified":true},{"name":"Pescado asqueroso","type":"add","diffs":["N","H","M"],"note":"Se recoge y se lanza a un tortoliano poseído para interrumpir a Mor'zahi.","verified":true}]},{"phase":"First Mate Nama","mechanics":[{"name":"Concha giratoria","type":"avoid","diffs":["N","H","M"],"note":"Conchas en cono que aturden a los jugadores — hay que apuntarlas al borde.","verified":true},{"name":"Golpes constantes","type":"tanque","diffs":["N","H","M"],"note":"Aumenta el daño físico de Nama contra el mismo objetivo con cada golpe.","verified":true}]},{"phase":"Scrollsage Iku","mechanics":[{"name":"Llamas ligadas al hielo","type":"cortable","diffs":["N","H","M"],"note":"Cast interrumpible — rotación de 2-3 jugadores.","verified":true},{"name":"Fragmentos trituradores","type":"tanque","diffs":["N","H","M"],"note":"Carga de tanque — cambio tras cada carga.","verified":true},{"name":"Nova de traslación","type":"raidwide","diffs":["N","H","M"],"note":"Teletransporte a un ranged marcado + daño de raid reducido por distancia.","verified":true}]},{"phase":"Ultimates","mechanics":[{"name":"Sorpresa explosiva (Gebbo)","type":"avoid","diffs":["N","H","M"],"note":"Champiñones saltarines + bombas — usar el champiñón para saltar la Ola explosiva.","verified":true},{"name":"Batacazo potente (Nama)","type":"soak","diffs":["N","H","M"],"note":"3 marcados reciben salto + repulsión repartida entre los cercanos.","verified":true},{"name":"Salva de Pirofrío (Iku)","type":"avoid","diffs":["N","H","M"],"note":"Proyectiles de Fuego/Escarcha que dejan zonas — cruzar el tipo opuesto las limpia con daño de raid.","verified":true}]},{"phase":"Mítico","mechanics":[{"name":"Ruptura de reliquia","type":"raidwide","diffs":["M"],"note":"Romper un cajón aplica sangrado a todo el raid; si no se rompe a tiempo, daño extra de raid.","verified":true}]}]},{"slug":"sszorak","name":"Sszorak","wing":"Ala 3: La Madriguera de la Sierpe","order":5,"phases":[{"phase":"Fase principal","mechanics":[{"name":"Depredador alfa","type":"tanque","diffs":["N","H","M"],"note":"Secuencia de 5 golpes (2 Despedazar, 2 Mutilar, 1 Tempestad) en orden aleatorio.","verified":true},{"name":"Despedazar","type":"tanque","diffs":["N","H","M"],"note":"Golpes en cono frontal; apuntarlo lejos del raid.","verified":true},{"name":"Mutilar","type":"soak","diffs":["N","H","M"],"note":"Ataque de veneno en cono repartido entre los golpeados; aplica Cuchillada mutilada.","verified":true},{"name":"Tempestad","type":"avoid","diffs":["N","H","M"],"note":"Vórtices de viento venenoso que dañan y ralentizan — esquivar.","verified":true},{"name":"Veneno corrosivo","type":"tanque","diffs":["N","H","M"],"note":"Carga de tanque — cambio sobre 6 cargas.","verified":true},{"name":"Oleada venenosa","type":"avoid","diffs":["N","H","M"],"note":"Jugadores asignados sueltan Quistes viscosos en marcas del suelo.","verified":true},{"name":"Residuo cáustico","type":"avoid","diffs":["H","M"],"note":"Heroico: charcos que suben 30% el daño recibido.","verified":true},{"name":"Vientos cruzados furiosos","type":"avoid","diffs":["N","H","M"],"note":"Viento direccional — emparejarse con quien mira al lado opuesto.","verified":true}]},{"phase":"Intermedio","mechanics":[{"name":"Vorágine aullante","type":"avoid","diffs":["N","H","M"],"note":"Vendavales que empujan por la plataforma.","verified":true},{"name":"Atrincherarse","type":"raidwide","diffs":["N","H","M"],"note":"Sszorak recibe +30% daño 25s — ventana de cooldowns de DPS.","verified":true}]},{"phase":"Mítico","mechanics":[{"name":"Furia de sierpe","type":"avoid","diffs":["M"],"note":"Marca a un jugador y acumula ira con el tiempo.","verified":true},{"name":"Ferocidad desmedida","type":"enrage","diffs":["M"],"note":"Condición de wipe al llegar a 100 de ira.","verified":true},{"name":"A la matanza","type":"soak","diffs":["M"],"note":"Carga al marcado si hay 14+ jugadores cerca — soak de carga.","verified":true},{"name":"Virulencia","type":"avoid","diffs":["M"],"note":"Daño de Naturaleza periódico que estalla al eliminarse — esparcirse.","verified":true}]}]},{"slug":"twin-fangs","name":"Los colmillos gemelos (Vexhul y Ithraz)","wing":"Ala 1: Los Volutadores de Almas","order":6,"phases":[{"phase":"Fase principal","mechanics":[{"name":"Veneno eterno","type":"oneshot","diffs":["N","H","M"],"note":"Veneno permanente y acumulable que no expira: daño de Naturaleza cada 1 s por acumulación. Con 10 acumulaciones el jugador muere. Solo el Festín voraz lo reduce (1 acumulación por jugador y festín), así que hay que llevar la cuenta de las acumulaciones de toda la banda.","verified":true},{"name":"Emanaciones tóxicas","type":"raidwide","diffs":["N","H","M"],"note":"Los colmillos gemelos impregnan el aire: daño de Naturaleza a todos cada 2 s durante todo el combate. Es presión de fondo para los sanadores.","verified":true},{"name":"Diluvio cáustico","type":"tanque","diffs":["N","H","M"],"note":"Vexhul inyecta toxinas a su objetivo actual durante 5 s (daño cada 0,5 s) y expulsa ácido a su alrededor: salpicaduras a 4 m que aplican Veneno eterno y crean Glóbulos cáusticos. El resto de la banda se mantiene lejos del objetivo. El tanque recibe Envenenado (+10 % de daño del Diluvio por acumulación, 1,5 min): hay que cambiar según las acumulaciones.","verified":true},{"name":"Glóbulo cáustico","type":"soak","diffs":["N","H","M"],"note":"Se forma un glóbulo ácido que explota a los 10 s: si alguien lo absorbe solo le afecta a él; si nadie lo hace, toda la banda recibe daño y una acumulación de Veneno eterno. Se asigna un jugador por glóbulo, preferiblemente con pocas acumulaciones. En Mítico cada muerte por Veneno eterno suelta 3 glóbulos.","verified":true},{"name":"Rompepiedra","type":"tanque","diffs":["N","H","M"],"note":"Ithraz ruge y repele a los jugadores, y luego golpea la plataforma en tres impactos seguidos (tres remolinos blancos): cada impacto hace daño físico enorme a quien esté a 4 m y suma +33 % de daño de Rompepiedra durante 90 s. Si un impacto no alcanza a nadie, toda la banda recibe daño que ignora la armadura y repulsión. Los tanques absorben todos los impactos, alternando entre ellos.","verified":true},{"name":"Aparición venenosa","type":"add","diffs":["N","H","M"],"note":"Vexhul invoca a su progenie (3 s): daño y una acumulación de Veneno eterno a todos, inevitable, y 3 engendros en el centro de la sala. Hay que contar con esa acumulación forzada y matar a los engendros rápido, antes de su segundo lanzamiento.","verified":true},{"name":"Flema corrosiva","type":"avoid","diffs":["N","H","M"],"note":"Cada engendro se fija en un jugador y le escupe toxinas en línea recta (5 s): daño de Naturaleza y Veneno eterno a quien alcance. El objetivo apunta la línea lejos de la banda y los demás se apartan.","verified":true},{"name":"Icor anillado","type":"avoid","diffs":["N","H","M"],"note":"Ithraz imbuye a varios jugadores de icor abyecto (3 s): un círculo que hace daño de las Sombras cada 1 s a quien esté dentro, se encoge y sube su daño con el tiempo. Los marcados caminan hasta el borde de la sala: al expirar deja Sangre cuajada durante 2 min, que ralentiza un 50 %.","verified":true},{"name":"Agitación en lo profundo","type":"avoid","diffs":["N","H","M"],"note":"Vexhul remueve el mar de veneno 6 s: daño de Naturaleza a todos cada 2 s y olas verdes que cruzan la plataforma. Quien es alcanzado por una ola recibe daño y una acumulación de Veneno eterno. Hay que esquivar entre las olas: son las acumulaciones más fáciles de evitar.","verified":true},{"name":"Festín voraz","type":"soak","diffs":["N","H","M"],"note":"Ithraz intenta devorar a los jugadores con 3 ataques rápidos (4,25 s): cada golpe reparte daño físico enorme entre los jugadores a 14 m y quita 1 acumulación de Veneno eterno (la única forma de reducirlas). Quien lo recibe queda Alimentado (+800 % de daño de Festín 8 s) y no puede soakear dos veces. Hacen falta tres grupos de 7 o más, uno por golpe; en Mítico cada golpe necesita al menos 4 jugadores.","verified":true},{"name":"Babas concentradas","type":"avoid","diffs":["N","H","M"],"note":"Si el objetivo de Vexhul está fuera de su alcance, lo cubre de babas que hacen daño de Naturaleza. Hay que mantenerla bien tanqueada.","verified":true},{"name":"Descarga coagulada","type":"avoid","diffs":["H","M"],"note":"Si el objetivo de Ithraz está fuera de su alcance, lo cubre de sangre que hace daño de las Sombras. Igual que con Vexhul, hay que mantenerlo tanqueado en su sitio.","verified":true}]},{"phase":"Intermedio (Sumersión)","mechanics":[{"name":"Sumersión","type":"avoid","diffs":["N","H","M"],"note":"Cuando se llega a 100 de energía (tras el segundo Festín voraz) los dos colmillos se sumergen y cambian de lado: la inmersión cubre la zona de veneno que hace daño de Naturaleza a quien esté a 6 m de cada impacto y deja Mancha nociva. Se repite tras cada dos series de acumulaciones; la tercera es el enrage duro.","verified":true},{"name":"Mancha nociva","type":"avoid","diffs":["N","H","M"],"note":"Charco que deja la Sumersión: daño de Naturaleza cada 1 s y +30 % de daño recibido a quien esté dentro. Hay que esquivarlo usando velocidad de movimiento.","verified":true},{"name":"Aluvión abyecto","type":"avoid","diffs":["N","H","M"],"note":"Vexhul canaliza 14 s un torrente continuo hacia delante: daño de Naturaleza cada 0,5 s y Veneno eterno a quien alcanza, con acumulaciones tan rápidas que matan. Se mueve en sentido contrario a las esferas que giran y se cruza el haz pronto: lo que queda detrás es seguro. Lo provoca el tanque que llevaba a Vexhul.","verified":true},{"name":"Tormenta sanguina","type":"avoid","diffs":["N","H","M"],"note":"Ithraz inunda la plataforma de pegotes de sangre durante 18 s: cada impacto hace daño de las Sombras a quien esté a 4 m y deja un charco de Sangre cuajada que ralentiza. Hay que esquivar sin dejar de girar alrededor del Aluvión abyecto.","verified":true}]},{"phase":"Enrage","mechanics":[{"name":"Cólera involutada","type":"enrage","diffs":["N","H","M"],"note":"Cuando muere una de las serpientes, la superviviente se consume de ira y gana un 30 % más de daño cada 3 s. No comparten vida, así que hay que matarlas casi a la vez.","verified":true},{"name":"Enrage tras la tercera Sumersión","type":"enrage","diffs":["N","H","M"],"note":"Si se llega a la tercera Sumersión (a 100 de energía) los dos jefes se mueven al centro y lanzan una lluvia cáustica que acaba el combate rápidamente. Hay que matar a las dos serpientes antes.","verified":true}]},{"phase":"Mítico","mechanics":[{"name":"Baluarte dentado","type":"cortable","diffs":["M"],"note":"Mítico. El Torrente de sangre protege cada Glóbulo cáustico con un baluarte: hace daño de las Sombras y repele a quien intente recogerlo mientras esté activo. Cualquier control (aturdimiento en área, rugido, etc.) lo interrumpe: hay que romperlo antes de absorber el glóbulo.","verified":true},{"name":"Torrente de sangre","type":"avoid","diffs":["M"],"note":"Mítico. Ithraz canaliza 5 s un torrente de sangre contra su objetivo: cada 1 s aplica un gran absorbente de sanación y forma un Baluarte dentado alrededor de cada glóbulo. El grupo del objetivo necesita sanación para superarlo.","verified":true},{"name":"Despertar de la prole","type":"cortable","diffs":["M"],"note":"Mítico. Ithraz se revuelve (3 s): nova de sangre a toda la banda y 10 crías de Ithraz aparecen en posiciones y orden aleatorios en los lados. Cada una lanza Ráfaga visceral y se va al agua si se la interrumpe. Hay que interrumpir todas: es la mecánica que más wipes causa.","verified":true},{"name":"Ráfaga visceral","type":"cortable","diffs":["M"],"note":"Mítico. Cada cría convulsiona (3 s) y desata una ráfaga de las Sombras a toda la banda con un DoT acumulable. Aguantar una es posible; varias suelen acabar con la banda, sobre todo al final del combate.","verified":true},{"name":"Sangre corrupta","type":"soak","diffs":["M"],"note":"Mítico. El Festín voraz expulsa varias fuentes de sangre espumosa durante un máximo de 8 s: cada una absorbe la sanación de los jugadores a 5 m y hay que absorberlas por completo antes de que expiren, o estallan con daño enorme de las Sombras a toda la banda. Los cuerpo a cuerpo evitan la repulsión del Festín para poder absorberlas.","verified":true}]}]},{"slug":"coiled-altar","name":"El Altar en Espiral","wing":"Ala 4: La Tumba de Ula'tek","order":7,"phases":[{"phase":"Fase 1 (Zul'jan)","mechanics":[{"name":"Colmillos del Altar en Espiral","type":"raidwide","diffs":["N","H","M"],"note":"Zul'jan canaliza 8 s el poder del altar: daño de Naturaleza a todos y 3 acumulaciones por segundo de Toxina de colmillos gemelos. Sus golpes cuerpo a cuerpo consumen esa toxina y suben mucho el daño al tanque en los siguientes ataques. Las bocas del altar escupen Terreno nocivo: hay que salir de los charcos.","verified":true},{"name":"Terreno nocivo","type":"avoid","diffs":["N","H","M"],"note":"Charcos de veneno que dejan las bocas del altar: daño de Naturaleza cada 1 s a quien esté dentro.","verified":true},{"name":"Diluvio tóxico","type":"add","diffs":["N","H","M"],"note":"El crisol escupe veneno por la cámara: daño a quien esté a 4 m del impacto y crea glóbulos de Veneno fusionado, que laten daño de Naturaleza a toda la banda hasta que se destruyen. Los glóbulos se llevan al montón central y se limpian con Cortar.","verified":true},{"name":"Veneno volátil","type":"avoid","diffs":["N","H","M"],"note":"Al pisar un glóbulo se pega al jugador: daño cada 1 s a quien esté a 5 m durante 5 s y, al acabar, deja un glóbulo nuevo. El portador no debe acercarse a otros y lo lleva al montón central.","verified":true},{"name":"Ruptura de veneno","type":"raidwide","diffs":["N","H","M"],"note":"Cada glóbulo que se destruye aplica a toda la banda un DoT de Naturaleza de 10 s acumulable. Cuando Zul'jan llega a 0 % detona todos los glóbulos que queden, así que hay que limpiar y usar un cooldown grande de banda al empujar.","verified":true},{"name":"Cortar","type":"tanque","diffs":["N","H","M"],"note":"Tajo frontal de 3 s al objetivo actual: daño físico en cono, destruye los venenos fusionados y las mutaciones virulentas, y aumenta muchísimo el daño que se recibe de Cortar durante unos 40 s. Hay que cambiar de tanque en cada lanzamiento y usarlo para limpiar glóbulos.","verified":true},{"name":"Afilahachas","type":"avoid","diffs":["N","H","M"],"note":"Hachas que repelen a quien esté a 4 m del impacto y luego recorren la arena durante 3 min, con daño cada 0,25 s que ignora la armadura. Hay que esquivarlas.","verified":true},{"name":"Colmillo de veneno","type":"dispel","diffs":["N","H","M"],"note":"Zul'jan lanza un hacha envenenada entre varios jugadores (2 s): daño de Naturaleza cada 2 s durante 14 s. Se disipa como veneno.","verified":true},{"name":"Guillotina","type":"soak","diffs":["N","H","M"],"note":"Zul'jan lanza su hacha a un jugador: daño físico dividido a partes iguales entre quienes estén a 9 m y +500 % de daño recibido de Guillotina durante 1,7 min. Hacen falta al menos 5 jugadores en el grupo; si no, la banda recibe una Ejecución letal. El hacha acaba explotando: Beso de viuda cerca y Toque de viuda más lejos, así que se entra y se sale por la puerta.","verified":true},{"name":"Beso de viuda","type":"avoid","diffs":["N","H","M"],"note":"Cuando termina la Guillotina, del hacha brota una columna letal que daña a todos a 40 m del impacto (Beso de viuda); más allá del radio solo se recibe Toque de viuda, mucho más suave.","verified":true},{"name":"Mutación virulenta","type":"avoid","diffs":["M"],"note":"Mítico. Cada Diluvio tóxico convierte parte de los glóbulos en 5 mutaciones virulentas que hay que limpiar antes del siguiente lanzamiento; las que queden explotan los glóbulos cercanos (20 Rupturas de veneno) y pueden eliminar a la banda. Pisar una la pega al jugador como Veneno mutagénico: 5 s de daño a quien esté a 8 m y deja una mutación nueva. Los orbes morados nunca deben tocar a otros morados ni verdes.","verified":true}]},{"phase":"Fase 2 (Malacrass)","mechanics":[{"name":"Marcha pavorosa","type":"avoid","diffs":["N","H","M"],"note":"Malacrass posee a varios jugadores: absorben daño mientras marchan hacia el borde de la plataforma y se precipitan. Hay que romper el escudo antes de que lleguen al borde; al romperlo salen manifestaciones del terror del poseído. Se necesita un aturdimiento y un agarre o anillo para devolver a quien se acerque al borde.","verified":true},{"name":"Fijación inquietante","type":"add","diffs":["N","H","M"],"note":"Cada manifestación del terror se fija en un jugador aleatorio y avanza hacia él mientras no la mire; si lo alcanza, lo posee con Marcha pavorosa. Es inmune (Inexpugnable) hasta que Corte de alma la elimina: el jugador la lleva al punto de reunión y la mira para frenarla.","verified":true},{"name":"Corte de alma","type":"tanque","diffs":["N","H","M"],"note":"Rayo de las Sombras de 4 s en cono frontal: aumenta muchísimo el daño que se recibe de Corte de alma y aplica un DoT de 45 s. Elimina las manifestaciones y deja Destino sepulcral en los golpeados. Hay que cambiar de tanque.","verified":true},{"name":"Destino sepulcral","type":"avoid","diffs":["N","H","M"],"note":"El alma del jugador se fractura en Trozos de alma por el suelo: hay que pisar todos antes de que expire el efecto (15 s) o el jugador muere. Cada trozo recogido hace daño de las Sombras.","verified":true},{"name":"Bomba de penumbra","type":"avoid","diffs":["N","H","M"],"note":"Malacrass marca a 3 jugadores (cuerpo a cuerpo, sanador y a distancia; 4 en Mítico) con marcas de las Sombras: a los 5 s explotan con daño a quien esté a 15 m y aplican Destino sepulcral. Hay que alejarse del grupo antes de que exploten. En Mítico también debilita el Escudo de espíritu.","verified":true},{"name":"Risotada espiritual","type":"add","diffs":["H","M"],"note":"Malacrass llama a los espíritus (3 s): aparecen copias de Volutador de almas malicioso en el lado opuesto de la sala. Hay que matarlos antes de que lleguen a 100 de energía.","verified":true},{"name":"Lamento de terror","type":"cortable","diffs":["H","M"],"note":"El volutador de almas malicioso grita: asusta a todos 5 s. Hay que interrumpirlo, pero tarde, porque cada interrupción hace que el add se mueva un poco.","verified":true},{"name":"Malicia vengativa","type":"raidwide","diffs":["H","M"],"note":"El espíritu despertado lanza explosiones oscuras a jugadores aleatorios cada 3 s mientras siga vivo.","verified":true},{"name":"Consumido por el resentimiento","type":"add","diffs":["H","M"],"note":"Al llegar a 100 de energía el volutador de almas malicioso se vuelve inmune a las interrupciones: hay que matarlo antes.","verified":true},{"name":"Ocaso eterno","type":"oneshot","diffs":["N","H","M"],"note":"Malacrass se rodea de un Velo del Crepúsculo (un enorme escudo que aplica Oscuridad agobiante, un absorbente de sanación acumulable) y prepara un ataque de 17 s: daño enorme y DoT a toda la banda, además de charcos en la arena. Hay que romper el escudo para interrumpirlo; es una comprobación de daño, no se cura a través de ella.","verified":true},{"name":"Descarga aterradora","type":"tanque","diffs":["N","H","M"],"note":"Descarga de las Sombras de relleno sobre el objetivo principal de Malacrass.","verified":true},{"name":"Presencia espantosa","type":"raidwide","diffs":["N","H","M"],"note":"Aura constante: daño de las Sombras a todos cada 2 s durante toda la fase.","verified":true},{"name":"Escudo de espíritu","type":"cortable","diffs":["M"],"note":"Mítico. Los volutadores aparecen con un escudo que reduce un 99 % el daño recibido; se debilita con Bombas de penumbra (hacen falta 2 impactos). Hay que romperlo, matar y interrumpir antes de 100 de energía y antes de la siguiente Marcha pavorosa.","verified":true},{"name":"Resonancia malévola","type":"avoid","diffs":["M"],"note":"Mítico. Si dos manifestaciones se tocan, los dos jugadores fijados reciben daño enorme de las Sombras cada 1 s durante 5 s. Hay que mantener los fantasmas separados.","verified":true}]},{"phase":"Intermedio (Nexo de almas)","mechanics":[{"name":"Nexo de almas","type":"raidwide","diffs":["N","H","M"],"note":"Malacrass canaliza 35 s: vincula su alma con la de Zul'jan, que recibe Regeneración fantasmal (se cura un 2 % de su vida por segundo, pero recibe un 100 % más de daño). Malacrass queda inmune (Guardia de la muerte, −99 % de daño). Es la ventana de Heroísmo: todo a Zul'jan.","verified":true},{"name":"Borrado espiritual","type":"soak","diffs":["N","H","M"],"note":"Los fragmentos de Malacrass se desprenden de Zul'jan y corren hacia él: cada uno que lo alcanza lo cura (Reclamar esencia: 3 % en Heroico, 10 % en Mítico). Hay que pisarlos antes: cada fragmento hace daño de las Sombras a toda la banda y suma un 20 % de daño de Borrado espiritual durante 2 s, acumulable. En Mítico se absorben en grupos de hasta 4.","verified":true}]},{"phase":"Fase 3 (Unión espiral)","mechanics":[{"name":"Ligado al alma","type":"enrage","diffs":["N","H","M"],"note":"Los dos jefes están ligados: si uno cae primero el otro se enfurece (más velocidad de ataque y más daño). Hay que mantenerlos juntos para el cleave, matarlos a la par y guardar los cooldowns grandes para el empuje final.","verified":true},{"name":"Guillotina funesta","type":"soak","diffs":["H","M"],"note":"Versión de las Sombras de la Guillotina: mismo grupo de al menos 5 (si no, Ejecución lúgubre a toda la banda); el golpe hace que el grupo absorba sanación. Al explotar, Abrazo de la Muerte cerca (40 m) y Susurro de la muerte más lejos.","verified":true},{"name":"Profanación del Altar en Espiral","type":"raidwide","diffs":["N","H","M"],"note":"Zul'jan profana el altar: barrera que absorbe sanación de todos y 3 acumulaciones por segundo de Toxina corrupta (sus golpes consumen la toxina y dejan un DoT de las Sombras acumulable al tanque). Es en la práctica el enrage: hay que matar a los jefes antes de la siguiente.","verified":true},{"name":"Terreno mancillado","type":"avoid","diffs":["N","H","M"],"note":"Suelo corrupto que deja el altar: quien lo pisa absorbe 85 000 de sanación cada 1 s. Hay que salir y preparar cooldowns de sanación.","verified":true},{"name":"Corte contagiado","type":"tanque","diffs":["N","H","M"],"note":"Tajo de 3 s en cono frontal con daño de las Sombras: aumenta muchísimo el daño que se recibe de Corte contagiado (45 s) y aplica Destino sepulcral. Destruye los venenos fusionados, las mutaciones virulentas y las manifestaciones del terror. Hay que cambiar de tanque con las acumulaciones.","verified":true},{"name":"Vuelven las mecánicas de la Fase 2","type":"raidwide","diffs":["N","H","M"],"note":"En la Fase 3 vuelven la Marcha pavorosa (la banda se coloca en el lado opuesto, los fijados dejan los fantasmas en el centro y el resto los orbes), la Bomba de penumbra y el Ocaso eterno (hay que romper el Velo del Crepúsculo para interrumpirlo y esquivar los charcos; el primer escudo es el más duro porque los cooldowns se gastaron en el intermedio). En Mítico los volutadores de almas aparecen con Bombas de penumbra y escudo, y tras el segundo escudo solo hay que interrumpirlos.","verified":true}]}]},{"slug":"ulatek","name":"Ula'tek","wing":"Ala 4: La Tumba de Ula'tek","order":8,"phases":[{"phase":"Fase 1","mechanics":[{"name":"Cólera de la madre","type":"tanque","diffs":["N","H","M"],"note":"Ula'tek repele a su objetivo y lo muerde: daño cada 0,3 s durante 3 s a quien esté a su alcance. Cada mordedura aplica Veneno de piedra (acumulable, 1,7 min) y Con cojera (−55 % de velocidad, 1 min). Si el objetivo está fuera de su alcance, lo recibe toda la banda. Hay que cambiar de tanque cuando se acumule mucho Veneno de piedra.","verified":true},{"name":"Vapuleo mefítico","type":"raidwide","diffs":["N","H","M"],"note":"Golpe de cola de 4 s: daño y repulsión a los jugadores a menos de 35 m. Los que estén fuera de ese radio reciben daño y un DoT de 10 s.","verified":true},{"name":"Embate de cascabel","type":"raidwide","diffs":["N","H"],"note":"Si nadie está en cuerpo a cuerpo con Ula'tek, golpea la plataforma con la cola y hace daño a toda la banda (recarga de 3 s). Siempre debe haber un tanque en melé.","verified":true},{"name":"Ira descontrolada","type":"raidwide","diffs":["N","H","M"],"note":"Si Ula'tek no puede atacar a nadie en melé mientras no está lanzando ni canalizando, hace daño físico a toda la banda.","verified":true},{"name":"Vapores necróticos","type":"raidwide","diffs":["N","H","M"],"note":"Daño de Naturaleza a todos cada 1 s durante todo el combate, acumulable: la curación de fondo necesaria sube con el tiempo.","verified":true},{"name":"Espirales espectrales","type":"soak","diffs":["N","H","M"],"note":"Las espirales aplastan la plataforma y todos reciben daño de Naturaleza, que se reparte entre los jugadores a menos de 10 m del impacto: hay que juntarse en dos grupos (izquierda y derecha) y entrar en cada golpe. Se revientan los huevos a la vez; en Mítico los portadores deben llegar al segundo golpe rápido.","verified":true},{"name":"Constrictor de almas","type":"soak","diffs":["H","M"],"note":"Ula'tek constriñe el alma de quien absorbe las espirales: durante 5 s no puede mitigar el daño del siguiente golpe. Por eso se rota entre dos grupos para que nadie absorba dos golpes seguidos.","verified":true},{"name":"Olas cáusticas","type":"avoid","diffs":["N","H","M"],"note":"Oleadas de veneno que cruzan la plataforma: daño al impactar y un DoT acumulable de 10 s a quien esté en su trayectoria. Los huevos que alcanzan eclosionan al instante y se convierten en víboras: hay que esquivar la línea y mantener los huevos fuera de ella.","verified":true},{"name":"Cáscara maligna","type":"add","diffs":["N","H"],"note":"Los huevos de Ula'tek se pegan a quien los toca y le hacen daño cada 1 s mientras los lleve. Hay que llevarlos lejos del veneno y de las olas, que los convertirían en víboras. En Mítico pasan a ser Caparazón nocivo.","verified":true},{"name":"Membrana pútrida","type":"avoid","diffs":["N","H","M"],"note":"Cuando eclosiona una víbora escamañublo, los huevos expulsan una membrana sobre los jugadores: daño de Naturaleza cada 1 s durante 30 s. Hay que evitar que las víboras eclosionen cerca de la banda.","verified":true},{"name":"Estallido de ácido","type":"avoid","diffs":["N","H","M"],"note":"La víbora escupe veneno a un jugador aleatorio (hechizo de 2,5 s): daño al impactar y un DoT de 18 s.","verified":true},{"name":"Picadura petrificante","type":"avoid","diffs":["H","M"],"note":"La víbora canaliza 5 s y se abalanza sobre un jugador aleatorio: convierte en piedra a quienes estén a menos de 10 m, absorbe parte de la curación recibida y hace daño cada 2 s. Hay que separarse del objetivo.","verified":true},{"name":"Picadura ponzoñosa","type":"tanque","diffs":["H","M"],"note":"La crudita de escamañublo muerde a su objetivo actual: daño de Naturaleza cada 1 s durante 10 s, acumulable. El tanque que la lleve debe rotar si se acumula.","verified":true},{"name":"Ira de la encadenada","type":"raidwide","diffs":["N","H","M"],"note":"Hechizo de 6,5 s. Durante 20 s todos reciben daño cada 4 s y caen desprendimientos de escombros en ubicaciones aleatorias. La furia expone el Corazón venenoso: es la primera ventana de daño. Hay que usar Heroísmo y los cooldowns de banda.","verified":true},{"name":"Desprendimiento de escombros","type":"avoid","diffs":["N","H","M"],"note":"Durante la Ira de la encadenada caen escombros en varios puntos: daño muy alto a quien esté a menos de 7 m del impacto.","verified":true},{"name":"Corazón venenoso","type":"raidwide","diffs":["N","H","M"],"note":"Queda expuesto 20 s y todo el daño que recibe aumenta un 100 %: ventana de Heroísmo. Todos los aspectos de Ula'tek comparten la vida (Vínculo de Ula'tek), así que el daño al corazón cuenta para el jefe.","verified":true},{"name":"Nube de toxinas","type":"avoid","diffs":["N","H","M"],"note":"Al terminar la fase aparecen nubes de toxinas que hacen daño de Naturaleza cada 1 s a quien se quede dentro.","verified":true},{"name":"Endurecido","type":"add","diffs":["M"],"note":"En Mítico la progenie de escamañublo tiene un caparazón que absorbe mucho daño y no pueden moverse ni recogerse hasta que se rompe. Los multi-DoT lo rompen de forma pasiva.","verified":true},{"name":"Matriz tóxica","type":"add","diffs":["M"],"note":"Mítico. Ula'tek arranca una cría en gestación del techo (canalización de 20 s): daño a quien esté a menos de 7 m del impacto y, al terminar, queda un engendro escamañublo que despierta tras 20 s.","verified":true},{"name":"Ráfaga supurante","type":"soak","diffs":["M"],"note":"Mítico. El engendro escamañublo crea una membrana (4 s) que estalla: daño y un DoT de 12 s a todos los que estén fuera de 10 m. Todo el grupo debe estar dentro de la burbuja cuando explote; los tanques controlan su posición.","verified":true},{"name":"Incubación tóxica","type":"soak","diffs":["M"],"note":"Mítico. Una Ula'tek espectral lanza una cascada de veneno (8 s) hacia el engendro que le da Bendición de la madre (menos daño recibido y más daño). Un jugador puede interceptar el veneno: recibe mucho daño y Quemadura tóxica (acumulable, 12 s), y cada impacto genera Olas cáusticas.","verified":true},{"name":"Caparazón nocivo","type":"avoid","diffs":["M"],"note":"Mítico. Los huevos nocivos hacen mucho daño cada 1 s al portador. Si dos portadores se acercan a menos de 3 m se produce una Salpicadura nociva y eclosiona una víbora. Al soltar el huevo queda Yema rancia (+200 % de daño del caparazón durante 20 s): no se deben encadenar recogidas.","verified":true}]},{"phase":"Fase 2","mechanics":[{"name":"Muda de las Sombras","type":"add","diffs":["N","H","M"],"note":"La escalamidad celadora muda de piel (3 s) y se arrastra a una nueva ubicación. Hay que llevarla a las escaleras para activar el teletransporte y matarla antes de su siguiente Gestación temblorosa.","verified":true},{"name":"Gestación temblorosa","type":"add","diffs":["N","H","M"],"note":"La celadora convierte las crías cercanas en una Nidada de escamañublo que eclosiona tras 20 s. Si sigue viva, las nidadas crecen y hay que romperlas antes de que nazcan, lo que retrasa mucho la fase.","verified":true},{"name":"Protección de celador","type":"avoid","diffs":["N","H","M"],"note":"La vida de la celadora envuelve los huevos: daño cada 1 s a los jugadores a menos de 7 m e impide tocarlos mientras siga viva.","verified":true},{"name":"Colmillos anhelantes","type":"raidwide","diffs":["N","H","M"],"note":"La celadora clava los colmillos en jugadores aleatorios (3 por lado en Heroico): daño cada 2 s y −45 % de velocidad mientras estén intactos. Al romperlos se aplica Vena contagiada a la banda, así que hay que escalonar las roturas (Heroico: de dos en dos; Mítico: un jugador primero y los otros cinco juntos en cuanto caiga el primer debuff).","verified":true},{"name":"Vena contagiada","type":"raidwide","diffs":["N","H","M"],"note":"Al romper los Colmillos anhelantes se aplica a toda la banda daño de Naturaleza cada 2 s durante 4 s, acumulable si se rompen varios a la vez.","verified":true},{"name":"Malicia","type":"cortable","diffs":["H"],"note":"La celadora libera su malicia (1,5 s): daño enorme cada 1 s durante 6 s a toda la banda. Hay que interrumpirla.","verified":true},{"name":"Caldera de escalamidad","type":"add","diffs":["N","H","M"],"note":"Punto de entrega de los huevos: los huevos pequeños se tiran primero y el huevo grande de escalamidad el último. Los huevos entregados desaparecen y no pueden eclosionar.","verified":true},{"name":"Cáscara de escalamidad","type":"avoid","diffs":["N","H","M"],"note":"Los huevos de escalamidad se pegan al jugador que los toca (daño cada 2 s). Si no se entregan, la bestia eclosiona a los 20 s.","verified":true},{"name":"Defecto: debilitada","type":"add","diffs":["N","H","M"],"note":"Si se interrumpe la gestación de la escalamidad voraz nace debilitada: recibe un 100 % más de daño y no puede lanzar Rugido terrorífico. Es un objetivo prioritario.","verified":true},{"name":"Grito de angustia","type":"cortable","diffs":["N","H","M"],"note":"La escalamidad debilitada grita (2,5 s): daño en 60 m y aturdimiento de 6 s. Hay que interrumpir el primer lanzamiento; en Mítico se asignan 3 interruptores por add.","verified":true},{"name":"Vapuleo desesperado","type":"avoid","diffs":["N","H","M"],"note":"La escalamidad debilitada ataca en cono (3 s): daño al impactar y un DoT de 6 s a quien esté en el cono.","verified":true},{"name":"Venganza","type":"add","diffs":["H","M"],"note":"Al morir una escalamidad debilitada, la otra se enfurece: +100 % de celeridad y de daño. Hay que matar a las dos casi a la vez.","verified":true},{"name":"Rugido terrorífico","type":"oneshot","diffs":["H","M"],"note":"Si la escalamidad voraz llega a nacer, ruge (2,5 s): daño enorme a la banda y aturdimiento de 20 s. No se puede dejar que lance.","verified":true},{"name":"Picadura ponzoñosa","type":"tanque","diffs":["H","M"],"note":"Las cruditas de escamañublo que nacen de los huevos muerden a su objetivo: daño cada 1 s durante 10 s, acumulable.","verified":true},{"name":"Veneno hirviente","type":"enrage","diffs":["M"],"note":"Mítico. Las cruditas se enfurecen a los 25 s y los engendros y chillones a los 30 s: +100 % de celeridad y de daño. Los enfurecidos lanzan Expulsión acídica, así que hay que matarlos antes.","verified":true},{"name":"Expulsión acídica","type":"raidwide","diffs":["M"],"note":"Mítico. El escamañublo enfurecido escupe veneno a toda la banda: daño y un DoT de 35 s acumulable. Un aturdimiento en la crudita enfurecida corta el lanzamiento.","verified":true}]},{"phase":"Intermedio","mechanics":[{"name":"Espirales espectrales (soaks en cadena)","type":"soak","diffs":["N","H","M"],"note":"Durante La Fragmentación las espirales se repiten (3 golpes en Normal, 6 en Heroico y 8 en Mítico). En Heroico el grupo 1 absorbe los golpes 1, 3 y 5 y el grupo 2 los 2, 4 y 6, corriendo de cola en cola; en Mítico se usan tres equipos. Hay que usar defensivos y poción de sanación.","verified":true},{"name":"Fractura de la plataforma","type":"avoid","diffs":["N","H","M"],"note":"Al final del intermedio la plataforma brilla y se rompe en 4 trozos lanzando a los jugadores por los aires: hay que colocarse a un lado y evitar el centro.","verified":true}]},{"phase":"Fase 3","mechanics":[{"name":"Llamada de la sierpe","type":"avoid","diffs":["N","H","M"],"note":"Rugido de 4 s: la prole cae del techo y hace daño a los jugadores a menos de 4 m de cada impacto. Genera una nidada en cada plataforma y, en las siguientes, también un chillón en una plataforma rota. Hay que separarse y salir de los círculos.","verified":true},{"name":"Mordedura de serpiente","type":"soak","diffs":["N","H","M"],"note":"Hechizo de 5 s: Ula'tek dispara colmillos a varios jugadores (un cuerpo a cuerpo, un sanador y un a distancia por grupo): daño y un DoT de 15 s. Al agotarse el jugador se convierte en Cadáver calcificado: quien esté a menos de 7 m puede absorber el veneno, pero recibe Purga volátil. Si nadie lo absorbe, el cadáver mata a la banda. Se hacen tres grupos de absorción.","verified":true},{"name":"Purga volátil","type":"avoid","diffs":["H","M"],"note":"Quien absorbe la Mordedura de serpiente la purga a los 5 s: estalla con daño y un DoT de 18 s acumulable para los que estén cerca, y aumenta un 200 % el daño que recibe de Veneno mortal. Hay que separarse antes de que estalle. En Mítico, al acabar libera Olas cáusticas en la dirección de la flecha: nunca hay que apuntarla a la banda.","verified":true},{"name":"Olas cáusticas","type":"avoid","diffs":["N","H","M"],"note":"Vuelven en la Fase 3 con huecos por los que colarse. En Mítico las dirige el jugador con la flecha de Purga volátil. Los huevos y nidadas que alcanzan se convierten en víboras.","verified":true},{"name":"Rondar a la presa","type":"oneshot","diffs":["H","M"],"note":"Ula'tek destruye parte de la plataforma (8 s en Mítico): daño enorme y repulsión a los jugadores a menos de 13 m, y los de fuera también reciben daño. Hay que salir de la zona que va a romperse.","verified":true},{"name":"Gestación serpenteante","type":"add","diffs":["M"],"note":"Mítico. La nidada serpenteante eclosiona y sale una víbora tras 20 s (canalización). Las nidadas se arrastran hacia el olor del veneno y las olas las convierten en víbora: los tanques las agarran hacia la pila de la banda.","verified":true},{"name":"Ecos sañosos","type":"cortable","diffs":["H","M"],"note":"El chillón de escamañublo grita (2,5 s): daño a todos, DoT de 6 s y aturdimiento de 6 s. Hay que interrumpirlo en cada lanzamiento.","verified":true},{"name":"Expulsión acídica","type":"raidwide","diffs":["H","M"],"note":"El chillón escupe veneno a toda la banda: daño y un DoT de 35 s acumulable. Hay que provocarlo, matarlo rápido y mantener 2 acumulaciones o menos.","verified":true},{"name":"Rotura de plataformas","type":"oneshot","diffs":["N","H","M"],"note":"Las plataformas se rompen una a una. La segunda rotura es el momento más duro de la fase: todos los defensivos. En la última plataforma solo hay una Mordedura de serpiente y una ola, y hay que matar a Ula'tek antes de la última rotura; saltar al agua justo antes da unos segundos extra.","verified":true},{"name":"Furia desatada","type":"enrage","diffs":["H","M"],"note":"Enrage duro: golpe masivo a la banda seguido de daño creciente cada segundo. Ula'tek debe estar casi muerta cuando empieza.","verified":true}]}]},{"slug":"nymrissa","name":"Nymrissa Clamaolas","wing":"Guarida: Gruta Ligada a la Marea","order":9,"phases":[{"phase":"Heroico y Mítico","mechanics":[{"name":"Burbuja atrayente","type":"add","diffs":["H","M"],"note":"Gran burbuja que atrae a los múrlocs cercanos; estalla después.","verified":true},{"name":"Mareas pulsátiles","type":"raidwide","diffs":["H","M"],"note":"Los rabiosos burbujaleta emiten daño de Escarcha periódico a todos — matar al llegar a la burbuja.","verified":true},{"name":"Remolinos turbulentos","type":"avoid","diffs":["H","M"],"note":"Remolinos que avanzan hacia la burbuja y dañan a quien esté en su trayectoria — dejan un hueco libre.","verified":true},{"name":"¡Pop!","type":"raidwide","diffs":["H","M"],"note":"La burbuja estalla: daño de Escarcha a todos + repulsión.","verified":true},{"name":"Escarcha escalofriante","type":"soak","diffs":["H","M"],"note":"Daño + ralentización de 6s; deja un Orbe congelado en cada afectado.","verified":true},{"name":"Orbe congelado","type":"soak","diffs":["H","M"],"note":"Soak obligatorio: daño + DoT acumulado + 20% más daño de Escarcha recibido 16s.","verified":true},{"name":"Destrozar","type":"raidwide","diffs":["H","M"],"note":"Un Orbe congelado no soakeado explota con gran daño de raid + DoT acumulado.","verified":true},{"name":"Chorro de agua","type":"tanque","diffs":["H","M"],"note":"Daño continuo + repulsión + carga de daño recibido — cambio de tanque. Elimina la Escarcha persistente.","verified":true},{"name":"Lluvia abisal","type":"raidwide","diffs":["H","M"],"note":"Canalización de 4s con daño de raid y DoT residual — peligroso si se solapa con otras mecánicas.","verified":true},{"name":"Poderío de clamaolas","type":"enrage","diffs":["H","M"],"note":"Enrage suave: sube el daño de Escarcha de Nymrissa con el tiempo.","verified":true},{"name":"Mareas sin fin","type":"enrage","diffs":["H","M"],"note":"Enrage duro: daño de raid constante hasta que alguien muere — hay que matar al jefe antes.","verified":true}]},{"phase":"Mítico","mechanics":[{"name":"Escudo de aguaniebla","type":"cortable","diffs":["M"],"note":"Las hieloescamas burbujaleta protegen a los múrlocs cercanos con 99% menos daño — prioridad de muerte.","verified":true},{"name":"Ráfaga de Escarcha","type":"raidwide","diffs":["M"],"note":"En Mítico, soakear un Orbe congelado también estalla con daño de raid — repartir los soaks.","verified":true}]}]},{"slug":"kithix","name":"Kith'ix","wing":"El Desatamiento de Kith'ix (Parche 12.1.5)","order":10,"phases":[{"phase":"Fase 1: Asalto del Enjambre del Vacío (100 % → 25 %)","mechanics":[{"name":"Enjambre del Vacío","type":"add","diffs":["N","H","M"],"note":"Abre portales durante 6 s: daño de Sombras a toda la banda e invoca al Mole venenosa, al Tejevacío y a alfazaques bombarderos. Hay que matar a los aqir antes de que Kith'ix llegue a 100 de energía.","verified":true},{"name":"Presencia imponente","type":"add","diffs":["N","H","M"],"note":"Los aqir a menos de 25 m de Kith'ix reciben un 75 % menos de daño: sepáralos del jefe antes de atacarlos. No protege a los huevos.","verified":true},{"name":"Devastación oscura / Devastado","type":"tanque","diffs":["N","H","M"],"note":"Golpe al tanque con daño de Sombras y físico a todo el que esté a menos de 15 m. Aplica Devastado (+150 % de daño físico y de Sombras durante 25 s): hay que cambiar de tanque en cada lanzamiento. En Heroico y Mítico deja una Lacravacua.","verified":true},{"name":"Lacravacua","type":"avoid","diffs":["H","M"],"note":"Zona que deja Devastación oscura: daña y lanza hacia atrás a quien la toque. Durante la oscuridad suelta Fragmentos de eclipse, así que colócala con cabeza.","verified":true},{"name":"Horrores inefables / Miedo sobrecogedor","type":"avoid","diffs":["N","H","M"],"note":"Varios jugadores quedan abrumados 6 s y luego sufren Miedo sobrecogedor: al acabar (o al disiparlo) gritan y dañan a la banda, menos cuanto más lejos estén de los demás. Sepárate del grupo.","verified":true},{"name":"Apéndice retorcido","type":"avoid","diffs":["N","H","M"],"note":"Tentáculos de Sombras junto a Kith'ix que golpean a todo el que esté en su camino. Esquívalos.","verified":true},{"name":"Extinguir","type":"oneshot","diffs":["N","H","M"],"note":"Onda de Sombras a toda la banda, casi letal, que además elimina el Abrazo de la Luz. Hay que coger antes un Abrazo de la Luz (−90 % de daño de Sombras hasta 8 s) o usar inmunidad/defensivo.","verified":true},{"name":"Abrazo de la Luz","type":"soak","diffs":["N","H","M"],"note":"Liadrin esparce chispas de Luz: recoger una reduce un 90 % el daño de Sombras hasta 8 s. Cógela justo antes de cada Extinguir.","verified":true},{"name":"Rugido venenoso","type":"avoid","diffs":["N","H","M"],"note":"Cono frontal del Mole venenosa: daño de Naturaleza y físico y empuje. El tanque de adds lo orienta lejos de la banda y lo arrastra hasta el Tejevacío.","verified":true},{"name":"Ocaso","type":"raidwide","diffs":["N","H","M"],"note":"Daño de Sombras a toda la banda del Tejevacío; cada lanzamiento seguido pega un 20 % más fuerte. Mátalo rápido, no se puede mover.","verified":true},{"name":"Tejer el Vacío","type":"avoid","diffs":["N","H","M"],"note":"El Tejevacío canaliza sobre jugadores al azar: daño de Sombras durante 8 s.","verified":true},{"name":"Reacción visceral / Jugos gástricos","type":"add","diffs":["N","H","M"],"note":"Los alfazaques bombarderos fijan a un jugador y explotan al contacto con cualquiera o a los 30 s, aplicando Jugos gástricos (DoT que se acumula). Se pueden agarrar con un grip y llevar al Mole venenosa, de uno en uno. En Mítico dejan huevos.","verified":true},{"name":"Incubación / Aguijón mental","type":"add","diffs":["H","M"],"note":"Al morir el Gigante o el Tejedor dejan huevos (en Mítico, también los escarabajos). Los que no se rompen eclosionan en aguijoneamentes, que vuelan a un jugador y lo aturden unos 5 s con Aguijón mental. Rompe los huevos: Presencia imponente no los protege.","verified":true}]},{"phase":"Intermedio: Oscuridad agobiante (a 100 de energía)","mechanics":[{"name":"Oscuridad agobiante / Asfixia","type":"avoid","diffs":["N","H","M"],"note":"Una tormenta de oscuridad se cierra poco a poco sobre la sala y daña a toda la banda. Dentro de ella estás pacificado, ralentizado y recibes mucho daño cada segundo (Asfixia): quédate en el Baluarte refulgente.","verified":true},{"name":"Frenesí oscuro","type":"add","diffs":["N","H","M"],"note":"Los aqir vivos al empezar la oscuridad doblan su velocidad de ataque y de movimiento, son inmunes a control de masas y dañan a la banda. Hay que matarlos antes de los 100 de energía.","verified":true},{"name":"Agarre abisal","type":"oneshot","diffs":["N","H","M"],"note":"Tentáculos agarran a jugadores al azar y los arrastran hacia la oscuridad con un gran absorbente de sanación. Si no se cura en 8 s, mueren.","verified":true},{"name":"Fragmento de eclipse","type":"soak","diffs":["H","M"],"note":"Las Lacravacuas sueltan fragmentos que avanzan despacio hacia Liadrin. Hay que interceptarlos en grupos de 3 por marca (amarilla: solo tanques; azul: 2 sanadores + a rango; naranja: 1 sanador + 2 a rango; luna: 3 a rango): el que lo toca recibe un DoT acumulable. Oleadas: 4, 5 y 6 en los tres intermedios.","verified":true},{"name":"Fulgor perdido","type":"raidwide","diffs":["H","M"],"note":"Cuando un Fragmento de eclipse llega a Liadrin daña a la banda y reduce el Baluarte refulgente; si pasan demasiados, desaparece la zona segura.","verified":true},{"name":"Baluarte refulgente","type":"soak","diffs":["N","H","M"],"note":"Barrera de Luz en el centro de la sala: es la zona segura del intermedio. Se debilita con cada Radiancia divina.","verified":true},{"name":"Radiancia divina / Agotado","type":"add","diffs":["N","H","M"],"note":"A 100 de energía Liadrin disipa la oscuridad y aturde a Kith'ix durante 8 s: es la ventana principal de daño. Cada uso deja Agotado y aumenta un 10 % el daño de la siguiente oscuridad.","verified":true}]},{"phase":"Fase 2: La última Luz (25 % → 0 %)","mechanics":[{"name":"Aullido estigio","type":"oneshot","diffs":["N","H","M"],"note":"Al llegar al 25 % aturde a toda la banda, absorbe a los adds y las habilidades activas y da paso al Eclipse óctuple. Termina todo lo anterior.","verified":true},{"name":"La última Luz / Gracia luminosa","type":"raidwide","diffs":["N","H","M"],"note":"Tras el Aullido estigio, Liadrin cura por completo a la banda y concede Gracia luminosa (+50 % de daño y de sanación el resto del combate): momento de Ansia de sangre y cooldowns.","verified":true},{"name":"Puerta de la nada","type":"avoid","diffs":["N","H","M"],"note":"Marca a 3 jugadores por lanzamiento (cuerpo a cuerpo, sanador y a rango): a los 5 s se abre una puerta en su posición que daña a los cercanos y esparce Fragmentos de la nada. Sepárate del grupo.","verified":true},{"name":"Fragmentos de la nada","type":"avoid","diffs":["N","H","M"],"note":"Fragmentos que salen de las puertas: cada impacto suma una acumulación de Anular. Esquívalos.","verified":true},{"name":"Anular","type":"oneshot","diffs":["N","H","M"],"note":"Cada Puerta o Fragmento de la nada suma una acumulación. Con 5 mueres (3 en Mítico).","verified":true},{"name":"Negación","type":"tanque","diffs":["N","H","M"],"note":"En Fase 2 sustituye a Devastación oscura en el tanque: +100 % de velocidad de movimiento, +100 % de daño físico recibido e inmunidad a los Fragmentos. Dura 8 s en Heroico y 12 s en Mítico y mata al tanque si expira. Se quita tocando una Puerta de la nada. En Mítico tiene 3 acumulaciones y hay que limpiar 3 puertas.","verified":true},{"name":"Restabilización explosiva","type":"raidwide","diffs":["N","H","M"],"note":"Al quitarse Negación: golpe fuerte a la banda cercana que destruye las Puertas y Fragmentos a menos de 10 m (las guías dicen 10-15 m).","verified":true},{"name":"Eclipse óctuple","type":"enrage","diffs":["N","H","M"],"note":"Enrage duro: los eclipses aparecen uno a uno y cada uno daña a toda la banda con Sombras. El octavo converge sobre Liadrin y mata a todos. Hay que matar al jefe antes.","verified":true}]}]}]};
